cd C:\invoice-work\a882719a\workspace; $f='src/ledger/credit-notes.mjs'; $t=gc $f -Raw $t=$t.Replace("Math.max(line.amount - credited[index].net, 0)","Math.max(line.net - credited[index].net, 0)") $t=$t.Replace("const available = Math.max(line.amount - soFar.net, 0);","const available = Math.max(line.net - soFar.net, 0);") $t=$t.Replace("if (amount <= 0 || amount > line.amount) {","if (amount <= 0 || amount > available) {") $t=$t.Replace("  const tax = taxForAmount(amount, line.taxRateBps);`n  credited[entry.lineIndex] = { net: soFar.net + amount, tax: soFar.tax + tax };","  // Tax goes back in step with the net, so that crediting a line in full gives
  // back exactly the tax that was charged on it, however many notes it took.
  const creditedNet = soFar.net + amount;
  const tax = scaleRounded(line.tax, creditedNet, line.net) - soFar.tax;
  credited[entry.lineIndex] = { net: creditedNet, tax: soFar.tax + tax };") $t=$t.Replace("import { taxForAmount } from '../tax/calculate.mjs';","import { scaleRounded } from '../core/rounding.mjs';") sc $f $t -NoNewline; git diff src/ledger/credit-notes.mjs | select -first 60

cd C:\invoice-work\a882719a\workspace; $f='src/book.mjs'; $t=gc $f -Raw $t=$t.Replace("  issueCreditNote,`n  remainingCreditable,`n} from","  issueCreditNote,`n  remainingCreditable,`n  reversalsFromInvoice,`n} from") $t=$t.Replace("  /** Everything already given back on an invoice's lines. */`n  function drawnAgainst(number) {`n    return notesOn(number);`n  }","  /**
   * Everything already given back on an invoice's lines: its credit notes, and
   * the credit lines on later invoices that reverse part of it.
   */
  function drawnAgainst(number) {
    const reversals = [...invoices.values()]
      .flatMap(reversalsFromInvoice)
      .filter((reversal) => reversal.invoiceNumber === number);
    return [...notesOn(number), ...reversals];
  }

  /** Cash received on an invoice that has not gone back to the customer yet. */
  function refundableOn(number) {
    const received = cashReceived(settlementsOn(number));
    const refunded = sumAmounts(notesOn(number).map((note) => note.settlement?.refunded ?? 0));
    return received - refunded;
  }") $t=$t.Replace("import { createSettlement, invoiceBalance }","import { cashReceived, createSettlement, invoiceBalance }") $t=$t.Replace("import { compareDates } from './core/dates.mjs';","import { compareDates } from './core/dates.mjs';`nimport { sumAmounts } from './core/money.mjs';") $t=$t.Replace("      openBalance: balanceOf(invoice),`n    });","      openBalance: balanceOf(invoice),`n      refundable: refundableOn(number),`n    });") $t=$t.Replace("    const invoice = buildInvoice({ ...input, accountCredit: account.balance(customerId, currency) });`n    invoices.set","    const invoice = buildInvoice({ ...input, accountCredit: account.balance(customerId, currency) });`n    invoiceNumbers.take();`n    invoices.set") $t=$t.Replace("number: invoiceNumbers.take(),","number: invoiceNumbers.peek(),") $t=$t.Replace("const invoice = input ? issue({ ...input, number: invoiceNumbers.take() }) : null;","const invoice = input ? issue(input) : null;") $t=$t.Replace("deferredRevenue({ invoices: allInvoices(), currency, asOf })","deferredRevenue({ invoices: allInvoices(), notes, currency, asOf })") sc $f $t -NoNewline; git diff src/book.mjs | select-string "^[+-]"
